/// Multiboot2 정보 구조체 (간단 버전)
#[repr(C)]
pub struct MultibootInfo {
    size: u32,
    reserved: u32,
}

/// 커널 메인 함수
#[no_mangle]
pub extern "C" fn kernel_main(_multiboot_info: u64) -> ! {
